#include <cstddef>
#include <iostream>
#include <vector>

struct Item {
    int key;
    char label;
};

struct Counts {
    std::size_t comparisons = 0;
    std::size_t merge_writes = 0;
};

void merge_sort(std::vector<Item>& values, std::vector<Item>& buffer,
                std::size_t first, std::size_t last, Counts& counts) {
    if (last - first < 2) return;
    const std::size_t mid = first + (last - first) / 2;
    merge_sort(values, buffer, first, mid, counts);
    merge_sort(values, buffer, mid, last, counts);

    std::size_t left = first;
    std::size_t right = mid;
    std::size_t out = first;
    while (left < mid && right < last) {
        ++counts.comparisons;
        if (values[left].key <= values[right].key)
            buffer[out++] = values[left++];
        else
            buffer[out++] = values[right++];
        ++counts.merge_writes;
    }
    while (left < mid) {
        buffer[out++] = values[left++];
        ++counts.merge_writes;
    }
    while (right < last) {
        buffer[out++] = values[right++];
        ++counts.merge_writes;
    }
    for (std::size_t i = first; i < last; ++i)
        values[i] = buffer[i];
}

int main() {
    std::vector<Item> values{{9, 'a'}, {4, 'b'}, {9, 'c'},
                             {2, 'd'}, {6, 'e'}};
    std::vector<Item> buffer(values.size());
    Counts counts;
    merge_sort(values, buffer, 0, values.size(), counts);
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i > 0) std::cout << ' ';
        std::cout << values[i].key << values[i].label;
    }
    std::cout << "\ncomparisons=" << counts.comparisons
              << ", merge writes=" << counts.merge_writes << '\n';
}
